@pytest.mark.parametrize('signum', [signal.SIGTERM, signal.SIGINT]) @pytest.mark.parametrize('stage', ['lint', 'selfcheck']) def test_foreground_signal_stops_stage_tree_checkpoints_and_resumes(library, tmp_path, signum, stage): install_native_battery(library) fixture = tmp_path / 'signal fixture'; fixture.mkdir() # GNU timeout and Bash job control create additional process groups in the # stage's session. Both descendants must stop, even with TERM ignored. filename = 'lint_generator.py' if stage == 'lint' else 'generator_selfcheck.py' (library / 'shared/tools' / filename).write_text(''' import json, os, signal, subprocess, sys, time from pathlib import Path root = Path(os.environ['CHECK_SIGNAL_FIXTURE']) if (root / 'resume').exists(): print('PASS recovered selfcheck'); sys.exit(0) signal.signal(signal.SIGTERM, signal.SIG_IGN) child = subprocess.Popen([sys.executable, '-c', 'import signal,time; signal.signal(signal.SIGTERM, signal.SIG_IGN); time.sleep(90)']) (root / 'pids.json').write_text(json.dumps([os.getpid(), child.pid])) print('fixture stage alive', flush=True) time.sleep(90) ''') out = tmp_path / 'check output' args = [sys.executable, '-m', 'arcpuzzles', '--library', str(library), 'check', TASK, '--battery', '--phase', 'after', '--timeout', '90', '--compact-results', '--out', str(out)] env = dict(os.environ, PYTHONPATH=str(SOURCE), CHECK_SIGNAL_FIXTURE=str(fixture)) controller = subprocess.Popen(args, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) pids = [] try: wait_until(lambda: (fixture / 'pids.json').exists()) pids = json.loads((fixture / 'pids.json').read_text()) > assert all(live(pid) for pid in pids) E assert False E + where False = all(<generator object test_foreground_signal_stops_stage_tree_checkpoints_and_resumes.<locals>.<genexpr> at 0x7f46558dee90>)
